return {
  remove: {
    hook: "onAttackResult", rateLimit: "oncePerRound",
    async promptOnPlayer(H, actor, ctx) {
      if (ctx.result !== "miss") return false;
      const zone = H.zone.of(actor);
      if (!zone) return false;
      const zones = [zone, ...H.zone.adjacent(zone)].filter((z) => H.zone.threatIn(z) > 0);
      if (!zones.length) return false;
      const picked = await H.ask.one({
        title: "Bristle", label: "Remove 1 Threat",
        options: zones.map(value => ({ value, label: value })),
        applyLabel: "Remove Threat",
      });
      if (picked) await H.threat.remove(actor, 1, picked);
      return true;
    },
  },
};
